        try:
            fuse_enabled = configer.fuse_enabled or False
            fuse_manager = servicer.fuse_manager
            mounted = bool(
                fuse_manager
                and fuse_manager.fuse_thread
                and fuse_manager.fuse_thread.is_alive()
