# src/adapters/danmaku/factory.py
# 弹幕源工厂 — 自动扫描 + 动态注册
#
# ★ 开发者注意：新增弹幕源无需修改本文件。
#   只需在 src/adapters/danmaku/ 下新建 .py，继承 DanmakuProvider 并设置
#   PROVIDER_NAME，本工厂在首次调用时自动扫描并注册。

import importlib
import inspect
import logging
import pkgutil
from pathlib import Path

from src.adapters.danmaku.base import DanmakuProvider

logger = logging.getLogger(__name__)

_REGISTRY: dict[str, type[DanmakuProvider]] = {}
_scanned = False


def _scan_providers() -> None:
    """
    扫描 src/adapters/danmaku/ 下所有模块，找到继承了 DanmakuProvider
    且设置了 PROVIDER_NAME 的类，自动注册进 _REGISTRY。
    """
    global _scanned
    if _scanned:
        return
    _scanned = True

    package_dir  = Path(__file__).parent
    package_name = "src.adapters.danmaku"

    for _, module_name, _is_pkg in pkgutil.iter_modules([str(package_dir)]):
        # 跳过 base / factory / __init__ 本身
        if module_name in ("base", "factory", "__init__"):
            continue
        try:
            module = importlib.import_module(f"{package_name}.{module_name}")
            for _, obj in inspect.getmembers(module, inspect.isclass):
                if (
                    issubclass(obj, DanmakuProvider)
                    and obj is not DanmakuProvider
                    and getattr(obj, "PROVIDER_NAME", "")
                ):
                    name = obj.PROVIDER_NAME
                    _REGISTRY[name] = obj
                    logger.debug("[DanmakuFactory] 已注册: %s → %s", name, obj.__name__)
        except Exception as e:
            logger.warning("[DanmakuFactory] 加载模块 %s 失败: %s", module_name, e)


class DanmakuFactory:
    """弹幕源工厂，提供注册查询和实例化能力。"""

    @staticmethod
    def create(provider_name: str, **kwargs) -> DanmakuProvider:
        """
        创建弹幕源实例（配置通过 kwargs 注入）。

        Usage::

            provider = DanmakuFactory.create("bilibili", api_key="xxx")
            meta, comments = await provider.fetch_danmaku("BV1xx411c7mD")

        Raises:
            ValueError: 不支持的弹幕源名称
        """
        _scan_providers()
        cls = _REGISTRY.get(provider_name)
        if cls is None:
            raise ValueError(
                f"不支持的弹幕源: {provider_name}，已注册: {list(_REGISTRY)}"
            )
        return cls(**kwargs)

    @staticmethod
    def list_providers() -> list[dict]:
        """列出所有已注册的弹幕源（含字段规格，供前端动态渲染配置表单）。"""
        _scan_providers()
        return [
            {
                "name":       cls.PROVIDER_NAME,
                "label":      cls.DISPLAY_NAME or cls.PROVIDER_NAME,
                "config_key": cls.CONFIG_KEY,
                "fields":     [f.to_dict() for f in cls.CONFIG_FIELDS],
            }
            for cls in _REGISTRY.values()
        ]

    @staticmethod
    def get_provider_class(provider_name: str) -> type[DanmakuProvider] | None:
        """返回 Provider 类（不实例化），用于反射/类型检查。"""
        _scan_providers()
        return _REGISTRY.get(provider_name)

