        """
        获取单个配置值
        """
        if key in ["PLUGIN_ALIGO_PATH", "MACHINE_ID"]:
            return getattr(self, key)
        if key == "aliyundrive_token":
            self._update_aliyun_token()
        return getattr(self, key, None)

