    def add_transfer_share(share_url: str = "") -> ShareApiData:
        """
        添加分享转存整理
        """
        if not configer.share_recieve_paths:
            return ShareApiData(code=-1, msg="用户未配置转存目录")

        if not share_url:
            return ShareApiData(code=-1, msg="未传入分享链接")

