            return ApiResponse(code=0, msg="获取状态成功", data=data)
        except Exception as e:
            logger.error(f"【FUSE】获取状态失败: {e}", exc_info=True)
            return ApiResponse(code=-1, msg=f"获取状态失败: {str(e)}", data=None)

