            logger.debug("[Monitor] Webhook 已关闭，忽略推送事件 %d 条", len(events))
            return

        now = time.time()
        accepted = 0
        for ev in events:
            source = ev.get("source", "webhook")
            action = ev.get("action", "")
            path   = ev.get("path", "")

            # 去重：5s 内相同 (action, path) 只处理一次
            dedup_key = f"{action}:{path}"
            last_seen = self._dedup_cache.get(dedup_key, 0)
