           {qrStatus === 'loading' && <Spin tip={t('p115.qrLoading')} />}
           {(qrStatus === 'waiting' || qrStatus === 'scanned') && qrData?.qrcode_content && (
             <div style={{ position: 'relative', display: 'inline-block' }}>
               <img src={qrData.qrcode_content} alt="QR Code"
