   const insertAtCursor = (snippet) => {
     const el = templateRef.current
     if (!el) { setUrlTemplate(s => s + snippet); return }
     const start = el.selectionStart ?? urlTemplate.length
     const end   = el.selectionEnd   ?? urlTemplate.length
