       <LocalDirPickerModal
         open={syncPickerState.open && syncPickerState.type === 'local'}
         onClose={() => setSyncPickerState(s => ({ ...s, open: false }))}
         onSelect={handleSyncDirSelected}
       />
     </div>
   )
